SELECT DISTINCT p.* FROM projects p
INNER JOIN project_skills ps ON p.id = ps.project_id
p.status = 1
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.summary LIKE CONCAT('%', #{keyword}, '%'))
AND ps.skill_id = #{skillId}
ORDER BY p.sort_order ASC, p.id DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE projects
name = #{name}, slug = #{slug}, summary = #{summary}, description = #{description}, cover_url = #{coverUrl}, github_url = #{githubUrl}, demo_url = #{demoUrl}, status = #{status}, sort_order = #{sortOrder},
WHERE id = #{id}
